/* Read-only previous bills; historical dues are never added to the current invoice. */
function customerBillingHistory(customerId,exclude={}){if(!customerId)return {rows:[],count:0,total:0,paid:0,due:0};let rows=[...db.jobs.map(b=>({key:'jobs',bill:b})),...db.sales.map(b=>({key:'sales',bill:b}))].filter(({key,bill})=>bill.customer===customerId&&bill.status!=='Cancelled'&&!(key===exclude.key&&bill.id===exclude.id)).map(({key,bill})=>({key,id:bill.id,date:bill.date||'',vehicle:bill.vehicleNumber||number(bill.bike)||'',type:key==='jobs'?'Job Card':'Spare Parts Sale',total:billTotals(bill).total,paid:paid(bill),due:due(bill)})).sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));return {rows,count:rows.length,total:round(rows.reduce((n,r)=>n+r.total,0)),paid:round(rows.reduce((n,r)=>n+r.paid,0)),due:round(rows.reduce((n,r)=>n+r.due,0))}}
function customerBillingRowsMarkup(rows){return rows.map(row=>'<div class="customerHistoryRow"><div><strong>'+esc(row.id)+'</strong><small>'+esc(displayDate(row.date))+' · '+esc(row.type)+(row.vehicle?' · '+esc(row.vehicle):'')+'</small></div><div>Total <b>'+money(row.total)+'</b> · Paid '+money(row.paid)+' · Due <b class="'+(row.due>0?'historyDue':'')+'">'+money(row.due)+'</b></div></div>').join('')}
function customerBillingMarkup(customerId,exclude={}){if(!customerId)return '<strong>Previous Billing</strong><p>Select a saved customer to see a short billing history.</p>';let history=customerBillingHistory(customerId,exclude);if(!history.count)return '<strong>Previous Billing</strong><p>No previous bills found for this customer.</p>';return '<div class="customerHistoryHeading"><strong>Previous Billing ('+history.count+')</strong><span>Previous dues: <b class="historyDue">'+money(history.due)+'</b></span></div><small class="historySummary">Billed '+money(history.total)+' · Paid '+money(history.paid)+' · All this customer’s vehicles</small>'+customerBillingRowsMarkup(history.rows.slice(0,3))+(history.count>3?'<details><summary>View '+(history.count-3)+' more previous bills</summary><div class="customerHistoryMore">'+customerBillingRowsMarkup(history.rows.slice(3))+'</div></details>':'')+'<small class="historySummary">Current bill excluded. Previous dues are shown for reference only.</small>'}
function addCustomerBillingSummary(){let form=$('#billForm');if(!form||!jobDraft||!['jobs','sales'].includes(jobDraft.key)||form.querySelector('.customerHistoryPanel'))return;let customer=form.querySelector('[name="customer"]');if(!customer)return;let panel=document.createElement('section');panel.className='customerHistoryPanel';panel.setAttribute('aria-live','polite');let anchor=form.querySelector('.savedBillingDetails');if(anchor)anchor.after(panel);else customer.closest('.field').after(panel);let key=jobDraft.key,id=jobDraft.id||jobDraft.record.id;function sync(){panel.hidden=form.dataset.walkin==='true';panel.innerHTML=customerBillingMarkup(customer.value,{key,id})}customer.addEventListener('change',sync);form._syncCustomerBilling=sync;sync()}
const billBeforeCustomerHistory=billForm;
billForm=function(key,id,initial){billBeforeCustomerHistory(key,id,initial);addCustomerBillingSummary()};
const walkinBeforeCustomerHistory=setWalkinMode;
setWalkinMode=function(form,enabled){walkinBeforeCustomerHistory(form,enabled);form._syncCustomerBilling?.()};
const invoiceBeforeCustomerHistory=invoice;
invoice=function(key,id){invoiceBeforeCustomerHistory(key,id);let bill=find(key,id),body=$('#modalBody');if(!bill||!bill.customer||!['jobs','sales'].includes(key)||!body||body.querySelector('.customerHistoryPanel'))return;body.insertAdjacentHTML('afterbegin','<section class="customerHistoryPanel invoiceHistoryPanel">'+customerBillingMarkup(bill.customer,{key,id})+'</section>')};
